mkdir -p /tmp/i18n-check && cat > src/i18n/tmp-check.test.ts <<'EOF'
import { expect, test } from 'vitest';
import { I18N } from '@gravity-ui/i18n';
import { en, ru, type AppKey } from './keysets';

test('switching language changes app strings, with en fallback', () => {
  const i18n = new I18N({ lang: 'en', fallbackLang: 'en', data: { en: { app: en }, ru: { app: ru } } });
  const t = i18n.keyset<AppKey>('app');
  expect(t('save')).toBe('Save');
  i18n.setLang('ru');
  expect(t('save')).toBe('Сохранить');
  expect(t('languageLabel')).toBe('Язык интерфейса');
  i18n.setLang('en');
  expect(t('save')).toBe('Save');
  // every key present in both languages
  for (const k of Object.keys(en)) expect(ru).toHaveProperty(k);
});
EOF
